// numeral.js type declarations
// hand-written, not generated by the build
// based on @types/numeral 2.0.5 (MIT) by Vincent Bortone, Kenneth Luján, Carlos Quiroga and Piotr Błażejewicz

export as namespace numeral;

/**
 * Creates a Numeral from a number, a string (unformatted with the current locale),
 * another Numeral, null, undefined or NaN.
 */
declare function numeral(input?: any): numeral.Numeral;

declare namespace numeral {
    type RegisterType = 'format' | 'locale';

    type RoundingFunction = (value: number) => number;

    interface Numeral {
        clone(): Numeral;
        format(inputString?: string, roundingFunction?: RoundingFunction): string;
        value(): number | null;
        input(): any;
        set(value: any): Numeral;
        add(value: any): Numeral;
        subtract(value: any): Numeral;
        multiply(value: any): Numeral;
        divide(value: any): Numeral;
        difference(value: any): number;
    }

    interface NumeralJSLocale {
        delimiters: {
            thousands: string;
            decimal: string;
        };
        abbreviations: {
            thousand: string;
            million: string;
            billion: string;
            trillion: string;
        };
        ordinal(num: number): string;
        currency: {
            symbol: string;
        };
    }

    interface NumeralJSLocales {
        [id: string]: NumeralJSLocale;
    }

    interface NumeralJSFormat {
        regexps: {
            format: RegExp;
            unformat?: RegExp | (() => RegExp);
        };
        format(value: number | null, format: string, roundingFunction: RoundingFunction): string;
        unformat?(value: string): number | null;
    }

    interface NumeralJSFormats {
        [id: string]: NumeralJSFormat;
    }

    interface NumeralJSOptions {
        currentLocale: string;
        zeroFormat: string | null;
        nullFormat: string | null;
        defaultFormat: string;
        scalePercentBy100: boolean;
    }

    /** Helpers used by the built-in formats and by format plugins */
    interface NumeralJSUtils {
        numberToFormat(value: number | null, format: string, roundingFunction?: RoundingFunction): string;
        stringToNumber(string: string): number | null;
        isNaN(value: any): boolean;
        includes(string: string, search: string): boolean;
        insert(string: string, subString: string, start: number): string;
        repeat(string: string, count: number): string;
        reduce<T, U>(array: ArrayLike<T>, callback: (accumulator: U, current: T, index: number, array: ArrayLike<T>) => U, initialValue: U): U;
        reduce<T>(array: ArrayLike<T>, callback: (accumulator: T, current: T, index: number, array: ArrayLike<T>) => T): T;
        multiplier(x: number): number;
        correctionFactor(...values: number[]): number;
        toFixed(value: number, maxDecimals: number, roundingFunction: RoundingFunction, optionals?: number): string;
        toNonExponentialString(value: number): string;
    }

    const version: string;
    const options: NumeralJSOptions;
    const formats: NumeralJSFormats;
    const locales: NumeralJSLocales;
    const fn: Numeral;
    const _: NumeralJSUtils;

    function isNumeral(value: any): value is Numeral;

    /** Sets the current locale if it is registered. Returns the current locale key. */
    function locale(key?: string): string;

    /** Returns the current locale data, or the data for `key`. Throws for unknown keys. */
    function localeData(key?: string): NumeralJSLocale;

    /** Restores every option to its default */
    function reset(): void;

    /** Output for 0. Non-strings clear it. */
    function zeroFormat(format?: string | null): void;

    /** Output for null. Non-strings clear it. */
    function nullFormat(format?: string | null): void;

    /** Format used when format() gets none. Non-strings set '0.0'. */
    function defaultFormat(format?: string): void;

    /** Whether the % format multiplies by 100. Non-booleans set true. */
    function scalePercentBy100(scalePercentBy100?: boolean): void;

    /** Registers a locale or a format. Throws if the name is already registered. */
    function register(what: 'locale', key: string, value: NumeralJSLocale): NumeralJSLocale;
    function register(what: 'format', key: string, value: NumeralJSFormat): NumeralJSFormat;
    function register(what: RegisterType, key: string, value: NumeralJSLocale | NumeralJSFormat): NumeralJSLocale | NumeralJSFormat;

    /** Checks that a string is a valid number in the given (or current) locale */
    function validate(value: any, culture?: string): boolean;
}

export = numeral;
